tg_add_returning.source:
#include <metal_stdlib>
using namespace metal;
kernel void k(device uint *A [[buffer(0)]], const device uint *B [[buffer(1)]],
              device uint *C [[buffer(2)]], threadgroup atomic_uint *S [[threadgroup(0)]],
              uint tid [[thread_position_in_grid]]) {
    atomic_store_explicit(&S[tid], 0x1000u + tid * 0x11u, memory_order_relaxed);
    threadgroup_barrier(mem_flags::mem_threadgroup);
    C[tid] = atomic_fetch_add_explicit(&S[tid], 1u, memory_order_relaxed);
    threadgroup_barrier(mem_flags::mem_threadgroup);
    A[tid] = atomic_load_explicit(&S[tid], memory_order_relaxed);
}

