kernel void k(device uint *A [[buffer(0)]], const device uint *B [[buffer(1)]],
              device uint *C [[buffer(2)]], threadgroup atomic_uint *S [[threadgroup(0)]],
              uint tid [[thread_position_in_grid]]) {
    if (tid == 0) atomic_store_explicit(&S[0], 0u, memory_order_relaxed);
    threadgroup_barrier(mem_flags::mem_threadgroup);
    C[tid] = atomic_fetch_add_explicit(&S[0], 1u, memory_order_relaxed);
    threadgroup_barrier(mem_flags::mem_threadgroup);
    if (tid == 0) A[0] = atomic_load_explicit(&S[0], memory_order_relaxed);
}
